"""Supplier-rebate settlement refresh (policy revision 4).

Usage (from /workspace):
    python refresh.py --source inputs/source.xlsx --as-of YYYY-MM-DD \
        --output output/settlement.xlsx [--previous output/archive/close-N.xlsx]

The script copies the source workbook (all source sheets and the human-owned
OperatorNotes notebook untouched), adds Detail / Summary / Dashboard sheets,
and writes reconciliation.json beside the output.  Settlement economics are
computed exactly in Python; Summary carries live formulas whose cached values
are the Python results.  When LibreOffice is available a copy is recalculated
and must agree with the Python results, otherwise the refresh fails.
"""
import argparse
import datetime as dt
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import zipfile
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation
from fractions import Fraction
from pathlib import Path

from openpyxl import load_workbook
from openpyxl.chart import BarChart, Reference
from openpyxl.utils import get_column_letter

SOURCE_SHEETS = ["Events", "Lines", "Products", "Aliases", "Contracts", "OperatorNotes"]
GENERATED_SHEETS = ["Detail", "Summary", "Dashboard"]
DETAIL_HEADERS = ["event_id", "purchase_line", "group", "quarter", "kind", "eligible_cents"]
SUMMARY_HEADERS = ["group", "quarter", "net_cents", "rate_bps", "entitlement",
                   "previous_entitlement", "adjustment"]
REQUIRED_COLUMNS = {
    "Events": ["event_id", "revision", "recorded_at", "kind", "line_id", "return_of",
               "vendor", "occurred_on", "qty", "unit", "price", "status"],
    "Lines": ["line_id", "sku"],
    "Products": ["sku", "units_per_pack", "eligible"],
    "Aliases": ["vendor", "valid_from", "valid_until", "group"],
    "Contracts": ["group", "quarter", "threshold_cents", "rate_bps"],
}
CENT = Decimal("0.01")
QUARTER_RE = re.compile(r"^\d{4}-Q[1-4]$")


class RefreshError(Exception):
    pass


# --------------------------------------------------------------------------
# Value normalisation
# --------------------------------------------------------------------------
def is_blank(value):
    return value is None or (isinstance(value, str) and value.strip() == "")


def text(value):
    if is_blank(value):
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def to_date(value, where):
    if is_blank(value):
        raise RefreshError(f"{where}: missing date")
    if isinstance(value, dt.datetime):
        return value.date()
    if isinstance(value, dt.date):
        return value
    raw = str(value).strip()
    if not re.match(r"^\d{4}-\d{2}-\d{2}([T ].*)?$", raw):
        raise RefreshError(f"{where}: {value!r} is not an ISO date")
    try:
        return dt.date.fromisoformat(raw[:10])
    except ValueError as exc:
        raise RefreshError(f"{where}: {value!r} is not a valid date") from exc


def to_decimal(value, where):
    if is_blank(value):
        raise RefreshError(f"{where}: missing number")
    if isinstance(value, bool):
        raise RefreshError(f"{where}: {value!r} is not a number")
    try:
        number = Decimal(str(value).strip())
    except InvalidOperation as exc:
        raise RefreshError(f"{where}: {value!r} is not a number") from exc
    if not number.is_finite():
        raise RefreshError(f"{where}: {value!r} is not a finite number")
    return number


def to_int(value, where):
    number = to_decimal(value, where)
    if number != number.to_integral_value():
        raise RefreshError(f"{where}: {value!r} must be a whole number")
    return int(number)


def to_bool(value, where):
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and value in (0, 1):
        return bool(value)
    raw = "" if value is None else str(value).strip().upper()
    if raw in ("TRUE", "YES", "Y", "1"):
        return True
    if raw in ("FALSE", "NO", "N", "0"):
        return False
    raise RefreshError(f"{where}: {value!r} is not a boolean")


def half_up(amount):
    """ROUND_HALF_UP of an exact Fraction/Decimal to an integer."""
    frac = Fraction(amount)
    sign = -1 if frac < 0 else 1
    frac = abs(frac)
    return sign * int((frac + Fraction(1, 2)).__floor__())


def quarter_of(day):
    return f"{day.year}-Q{(day.month - 1) // 3 + 1}"


def read_table(wb, name):
    if name not in wb.sheetnames:
        raise RefreshError(f"source workbook is missing sheet {name!r}")
    data = list(wb[name].iter_rows(values_only=True))
    if not data:
        raise RefreshError(f"sheet {name!r} is empty")
    headers = [text(h) for h in data[0]]
    missing = [c for c in REQUIRED_COLUMNS[name] if c not in headers]
    if missing:
        raise RefreshError(f"sheet {name!r} is missing columns {missing}")
    if len(set(h for h in headers if h)) != len([h for h in headers if h]):
        raise RefreshError(f"sheet {name!r} has duplicate column headers")
    rows = []
    for index, values in enumerate(data[1:], start=2):
        if all(is_blank(v) for v in values):
            continue
        record = {h: v for h, v in zip(headers, values) if h}
        record["_row"] = index
        rows.append(record)
    return rows


# --------------------------------------------------------------------------
# Reference data
# --------------------------------------------------------------------------
def load_reference(wb):
    lines = {}
    for r in read_table(wb, "Lines"):
        where = f"Lines row {r['_row']}"
        line_id, sku = text(r["line_id"]), text(r["sku"])
        if not line_id or not sku:
            raise RefreshError(f"{where}: line_id and sku are required")
        if line_id in lines and lines[line_id] != sku:
            raise RefreshError(f"{where}: line {line_id!r} maps to conflicting SKUs")
        lines[line_id] = sku

    products = {}
    for r in read_table(wb, "Products"):
        where = f"Products row {r['_row']}"
        sku = text(r["sku"])
        if not sku:
            raise RefreshError(f"{where}: sku is required")
        upp = to_decimal(r["units_per_pack"], f"{where} units_per_pack")
        if upp <= 0:
            raise RefreshError(f"{where}: units_per_pack must be positive")
        item = (Fraction(upp), to_bool(r["eligible"], f"{where} eligible"))
        if sku in products and products[sku] != item:
            raise RefreshError(f"{where}: SKU {sku!r} is defined inconsistently")
        products[sku] = item

    aliases = {}
    for r in read_table(wb, "Aliases"):
        where = f"Aliases row {r['_row']}"
        vendor, group = text(r["vendor"]), text(r["group"])
        if not vendor or not group:
            raise RefreshError(f"{where}: vendor and group are required")
        start = to_date(r["valid_from"], f"{where} valid_from")
        end = None if is_blank(r["valid_until"]) else to_date(r["valid_until"], f"{where} valid_until")
        if end is not None and end <= start:
            raise RefreshError(f"{where}: valid_until must be after valid_from")
        aliases.setdefault(vendor, []).append((start, end, group, r["_row"]))

    contracts = {}
    for r in read_table(wb, "Contracts"):
        where = f"Contracts row {r['_row']}"
        group, quarter = text(r["group"]), text(r["quarter"])
        if not group or not quarter or not QUARTER_RE.match(quarter):
            raise RefreshError(f"{where}: group and a YYYY-Qn quarter are required")
        for col in ("threshold_cents", "rate_bps"):
            if not isinstance(r[col], (int, float)) or isinstance(r[col], bool):
                raise RefreshError(f"{where}: {col} must be a numeric cell (live formulas read it)")
        threshold = to_int(r["threshold_cents"], f"{where} threshold_cents")
        rate = to_decimal(r["rate_bps"], f"{where} rate_bps")
        if rate < 0:
            raise RefreshError(f"{where}: rate_bps must be nonnegative")
        tiers = contracts.setdefault((group, quarter), {})
        if threshold in tiers and tiers[threshold] != rate:
            raise RefreshError(f"{where}: duplicate threshold {threshold} with different rates")
        tiers[threshold] = rate
    return lines, products, aliases, contracts


def group_for(aliases, vendor, day, where):
    matches = {g for start, end, g, _ in aliases.get(vendor, [])
               if start <= day and (end is None or day < end)}
    if not matches:
        raise RefreshError(f"{where}: no Aliases interval for vendor {vendor!r} on {day}")
    if len(matches) > 1:
        raise RefreshError(f"{where}: overlapping Aliases intervals for vendor {vendor!r} on {day}")
    return matches.pop()


def rate_for(contracts, key, net_cents):
    tiers = contracts.get(key, {})
    eligible = [t for t in tiers if t <= max(0, net_cents)]
    if not eligible:
        return None
    return tiers[max(eligible)]


def entitlement_for(net_cents, rate_bps):
    return Decimal(half_up(Fraction(net_cents) * Fraction(rate_bps) / 10000)) / 100


# --------------------------------------------------------------------------
# Event selection and valuation
# --------------------------------------------------------------------------
ECONOMIC_FIELDS = ["kind", "line_id", "return_of", "vendor", "occurred_on", "qty", "unit",
                   "price", "status"]


def normalise_event(r):
    where = f"Events row {r['_row']}"
    event = {"_row": r["_row"], "_raw": r}
    event["event_id"] = text(r["event_id"])
    if not event["event_id"]:
        raise RefreshError(f"{where}: event_id is required")
    event["revision"] = to_decimal(r["revision"], f"{where} revision")
    event["recorded_at"] = to_date(r["recorded_at"], f"{where} recorded_at")
    event["status"] = (text(r["status"]) or "").upper()
    if event["status"] not in ("ACTIVE", "VOID"):
        raise RefreshError(f"{where}: status must be ACTIVE or VOID, got {r['status']!r}")
    event["kind"] = (text(r["kind"]) or "").upper() or None
    event["line_id"] = text(r["line_id"])
    event["return_of"] = text(r["return_of"])
    event["vendor"] = text(r["vendor"])
    event["unit"] = (text(r["unit"]) or "").upper() or None
    event["occurred_on"] = None if is_blank(r["occurred_on"]) else to_date(r["occurred_on"], f"{where} occurred_on")
    event["qty"] = None if is_blank(r["qty"]) else to_decimal(r["qty"], f"{where} qty")
    event["price"] = None if is_blank(r["price"]) else to_decimal(r["price"], f"{where} price")
    return event


def validate_active(event):
    where = f"Events row {event['_row']} ({event['event_id']})"
    if event["kind"] not in ("BUY", "RETURN"):
        raise RefreshError(f"{where}: kind must be BUY or RETURN")
    required = ["occurred_on", "qty", "unit"]
    required += ["line_id", "vendor", "price"] if event["kind"] == "BUY" else ["return_of"]
    for field in required:
        if event[field] is None:
            raise RefreshError(f"{where}: active {event['kind']} requires {field}")
    if event["unit"] not in ("PACK", "EA"):
        raise RefreshError(f"{where}: unit must be PACK or EA")
    if event["qty"] < 0:
        raise RefreshError(f"{where}: qty must be nonnegative")
    if event["kind"] == "BUY" and event["price"] < 0:
        raise RefreshError(f"{where}: price must be nonnegative")


def select_events(raw_rows, as_of):
    by_id = {}
    for r in raw_rows:
        event = normalise_event(r)
        if event["recorded_at"] > as_of:
            continue
        by_id.setdefault(event["event_id"], []).append(event)

    selected = {}
    for event_id, revisions in by_id.items():
        top = max(e["revision"] for e in revisions)
        copies = [e for e in revisions if e["revision"] == top]
        first = copies[0]
        for other in copies[1:]:
            if any(first[f] != other[f] for f in ECONOMIC_FIELDS):
                raise RefreshError(
                    f"event {event_id!r} revision {top} has conflicting copies "
                    f"(Events rows {first['_row']} and {other['_row']})")
        chosen = dict(first)
        if chosen["status"] == "VOID" and chosen["occurred_on"] is None:
            # A bare VOID marker inherits the date of the revision it cancels.
            earlier = sorted((e for e in revisions if e["occurred_on"] is not None),
                             key=lambda e: e["revision"])
            if earlier:
                chosen["occurred_on"] = earlier[-1]["occurred_on"]
        selected[event_id] = chosen
    return selected


def convert_qty(qty, from_unit, to_unit, units_per_pack):
    qty = Fraction(qty)
    if from_unit == to_unit:
        return qty
    if from_unit == "EA" and to_unit == "PACK":
        return qty / units_per_pack
    return qty * units_per_pack


def build_detail(selected, as_of, lines, products, aliases):
    for event in selected.values():
        if event["status"] == "ACTIVE":
            validate_active(event)

    buys_by_line = {}
    for event in selected.values():
        if event["status"] == "ACTIVE" and event["kind"] == "BUY":
            if event["line_id"] in buys_by_line:
                raise RefreshError(
                    f"line_id {event['line_id']!r} is used by more than one active BUY "
                    f"({buys_by_line[event['line_id']]['event_id']}, {event['event_id']})")
            buys_by_line[event["line_id"]] = event

    detail, voids = [], []
    for event_id in sorted(selected):
        event = selected[event_id]
        if event["status"] == "VOID":
            if event["occurred_on"] is None or event["occurred_on"] <= as_of:
                voids.append(event_id)
            continue
        if event["occurred_on"] > as_of:
            continue
        where = f"Events row {event['_row']} ({event_id})"
        buy = event if event["kind"] == "BUY" else buys_by_line.get(event["return_of"])
        if buy is None:
            raise RefreshError(f"{where}: return_of {event['return_of']!r} is not an active BUY line")
        line_id = buy["line_id"]
        if line_id not in lines:
            raise RefreshError(f"{where}: line {line_id!r} is not in Lines")
        sku = lines[line_id]
        if sku not in products:
            raise RefreshError(f"{where}: SKU {sku!r} is not in Products")
        units_per_pack, eligible = products[sku]
        group = group_for(aliases, buy["vendor"], buy["occurred_on"], where)
        quarter = quarter_of(buy["occurred_on"])
        qty = convert_qty(event["qty"], event["unit"], buy["unit"], units_per_pack)
        cents = half_up(qty * Fraction(buy["price"]) * 100)
        if event["kind"] == "RETURN":
            cents = -cents
        detail.append({
            "event_id": event["_raw"]["event_id"],
            "event_key": event_id,
            "purchase_line": buy["_raw"]["line_id"],
            "group": group,
            "quarter": quarter,
            "kind": event["kind"],
            "eligible_cents": cents if eligible else 0,
            "gross_cents": cents,
            "sku": sku,
            "eligible": eligible,
        })
    return detail, voids


# --------------------------------------------------------------------------
# Previous approved close
# --------------------------------------------------------------------------
def header_index(ws, required, label):
    headers = [text(c.value) for c in next(ws.iter_rows(min_row=1, max_row=1))]
    missing = [h for h in required if h not in headers]
    if missing:
        raise RefreshError(f"{label}: missing columns {missing}")
    return {h: headers.index(h) for h in required}


def load_previous(path):
    if not path.is_file():
        raise RefreshError(f"previous approved close {path} does not exist")
    try:
        values_wb = load_workbook(path, data_only=True)
    except Exception as exc:
        raise RefreshError(f"cannot read previous close {path}: {exc}") from exc
    if "Summary" not in values_wb.sheetnames:
        raise RefreshError(f"previous close {path} has no Summary sheet")
    ws = values_wb["Summary"]
    idx = header_index(ws, ["group", "quarter", "entitlement"], f"{path} Summary")
    keys, missing_cache = {}, []
    for row in ws.iter_rows(min_row=2, values_only=True):
        group, quarter = text(row[idx["group"]]), text(row[idx["quarter"]])
        if not group or not quarter or not QUARTER_RE.match(quarter):
            continue  # blank or totals rows are not keys
        if (group, quarter) in keys:
            raise RefreshError(f"previous close {path} repeats Summary key {group} {quarter}")
        value = row[idx["entitlement"]]
        if value is None or isinstance(value, str):
            missing_cache.append((group, quarter))
            keys[(group, quarter)] = None
        else:
            keys[(group, quarter)] = to_decimal(value, f"{path} Summary entitlement").quantize(CENT, ROUND_HALF_UP)
    if missing_cache:
        # Formulas saved without cached values: evaluate them from the archive's own sheets.
        recomputed = recompute_archive(values_wb, path)
        for key in missing_cache:
            keys[key] = recomputed.get(key, Decimal("0.00"))
    return keys


def recompute_archive(wb, path):
    for name in ("Detail", "Contracts"):
        if name not in wb.sheetnames:
            raise RefreshError(f"previous close {path} lacks cached entitlements and a {name} sheet")
    ws = wb["Detail"]
    idx = header_index(ws, ["group", "quarter", "eligible_cents"], f"{path} Detail")
    nets = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        group, quarter = text(row[idx["group"]]), text(row[idx["quarter"]])
        if group and quarter:
            nets[(group, quarter)] = nets.get((group, quarter), 0) + to_int(
                row[idx["eligible_cents"]], f"{path} Detail eligible_cents")
    _, _, _, contracts = load_reference_contracts_only(wb)
    result = {}
    for key, net in nets.items():
        net = max(0, net)
        rate = rate_for(contracts, key, net) or Decimal(0)
        result[key] = entitlement_for(net, rate)
    return result


def load_reference_contracts_only(wb):
    contracts = {}
    for r in read_table(wb, "Contracts"):
        group, quarter = text(r["group"]), text(r["quarter"])
        if group and quarter and not is_blank(r["threshold_cents"]):
            contracts.setdefault((group, quarter), {})[to_int(r["threshold_cents"], "Contracts")] = \
                to_decimal(r["rate_bps"], "Contracts")
    return None, None, None, contracts


# --------------------------------------------------------------------------
# Workbook output
# --------------------------------------------------------------------------
def summary_formulas(row):
    det = "Detail!$F:$F,Detail!$C:$C,$A{r},Detail!$D:$D,$B{r}".format(r=row)
    key = "Contracts!$A:$A,$A{r},Contracts!$B:$B,$B{r}".format(r=row)
    tier = f'_xlfn.MAXIFS(Contracts!$C:$C,{key},Contracts!$C:$C,"<="&$C{row})'
    return {
        "C": f"=MAX(0,SUMIFS({det}))",
        "D": f"=_xlfn.MAXIFS(Contracts!$D:$D,{key},Contracts!$C:$C,{tier})",
        # Exact ROUND_HALF_UP to cents of net_cents*rate_bps/1,000,000 (integer arithmetic).
        "E": f"=INT(($C{row}*$D{row}+5000)/10000)/100",
        "G": f"=ROUND($E{row}-$F{row},2)",
    }


def number_literal(value):
    if isinstance(value, Decimal):
        value = float(value) if value != value.to_integral_value() else int(value)
    return repr(value) if isinstance(value, float) else str(value)


def inject_cached_values(path, sheet_name, cached):
    """Store Python-computed results as cached values of the Summary formulas."""
    tmp = path.with_name(path.name + ".cache")
    with zipfile.ZipFile(path) as zin:
        workbook_xml = zin.read("xl/workbook.xml").decode()
        rels_xml = zin.read("xl/_rels/workbook.xml.rels").decode()
        m = re.search(r'<sheet[^>]*name="%s"[^>]*r:id="([^"]+)"' % re.escape(sheet_name), workbook_xml)
        rid = m.group(1)
        target = re.search(r'<Relationship[^>]*Id="%s"[^>]*Target="([^"]+)"' % re.escape(rid), rels_xml)
        if target is None:
            target = re.search(r'<Relationship[^>]*Target="([^"]+)"[^>]*Id="%s"' % re.escape(rid), rels_xml)
        member = target.group(1).lstrip("/")
        member = member if member.startswith("xl/") else "xl/" + member
        sheet_xml = zin.read(member).decode()

        def repl(match):
            ref = match.group(1)
            if ref not in cached:
                return match.group(0)
            return f'<c r="{ref}"{match.group(2)}><f>{match.group(3)}</f><v>{number_literal(cached[ref])}</v></c>'

        new_xml, count = re.subn(r'<c r="([A-Z]+\d+)"([^>]*)><f>(.*?)</f>(?:<v\s*/>|<v>[^<]*</v>)?</c>',
                                 repl, sheet_xml)
        if count < len(cached):
            raise RefreshError("could not attach cached values to Summary formulas")
        with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = new_xml.encode() if item.filename == member else zin.read(item.filename)
                zout.writestr(item, data)
    os.replace(tmp, path)


def write_workbook(source_path, out_tmp, detail, summary_rows):
    wb = load_workbook(source_path)
    for name in GENERATED_SHEETS:
        if name in wb.sheetnames:
            del wb[name]

    ws = wb.create_sheet("Detail")
    ws.append(DETAIL_HEADERS)
    for d in detail:
        ws.append([d["event_id"], d["purchase_line"], d["group"], d["quarter"], d["kind"],
                   d["eligible_cents"]])
    ws.freeze_panes = "A2"

    ws = wb.create_sheet("Summary")
    ws.append(SUMMARY_HEADERS)
    cached = {}
    for i, s in enumerate(summary_rows, start=2):
        f = summary_formulas(i)
        ws.append([s["group"], s["quarter"], f["C"], f["D"], f["E"], float(s["previous"]), f["G"]])
        cached.update({f"C{i}": s["net_cents"], f"D{i}": s["rate_bps"],
                       f"E{i}": s["entitlement"], f"G{i}": s["adjustment"]})
        for col in "EFG":
            ws[f"{col}{i}"].number_format = "#,##0.00"
    for col, width in zip("ABCDEFG", (14, 10, 14, 10, 14, 20, 14)):
        ws.column_dimensions[col].width = width
    ws.freeze_panes = "A2"

    dash = wb.create_sheet("Dashboard")
    dash["A1"] = "Rebate adjustment by group/quarter (linked to Summary!G)"
    last = max(2, len(summary_rows) + 1)
    chart = BarChart()
    chart.type = "col"
    chart.grouping = "clustered"
    chart.title = "Settlement adjustment vs. previous approved close"
    chart.y_axis.title = "Adjustment ($)"
    chart.x_axis.title = "Group"
    chart.x_axis.delete = False
    chart.y_axis.delete = False
    chart.y_axis.number_format = "#,##0.00"
    chart.legend = None
    data = Reference(wb["Summary"], min_col=7, min_row=1, max_row=last)
    cats = Reference(wb["Summary"], min_col=1, min_row=2, max_row=last)
    chart.add_data(data, titles_from_data=True)
    chart.set_categories(cats)
    for series in chart.series:
        series.invertIfNegative = False
    chart.width, chart.height = 24, 12
    dash.add_chart(chart, "A3")

    wb.calculation.fullCalcOnLoad = True
    wb.save(out_tmp)
    inject_cached_values(out_tmp, "Summary", cached)


def recalc_check(path, summary_rows):
    """Recalculate a copy with LibreOffice and compare with the Python results."""
    soffice = shutil.which("soffice") or shutil.which("libreoffice")
    if not soffice:
        print("warning: LibreOffice not found; skipped independent recalculation check", file=sys.stderr)
        return False
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        copy = tmp / "recalc_in.xlsx"
        shutil.copyfile(path, copy)
        outdir = tmp / "out"
        cmd = [soffice, f"-env:UserInstallation=file://{tmp / 'profile'}", "--headless",
               "--norestore", "--convert-to", "xlsx", "--outdir", str(outdir), str(copy)]
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
        except subprocess.TimeoutExpired as exc:
            raise RefreshError("LibreOffice recalculation timed out") from exc
        result = outdir / copy.name
        if proc.returncode != 0 or not result.exists():
            raise RefreshError(f"LibreOffice recalculation failed: {proc.stderr.strip() or proc.stdout.strip()}")
        ws = load_workbook(result, data_only=True)["Summary"]
        for i, s in enumerate(summary_rows, start=2):
            got = [ws.cell(i, c).value for c in (3, 4, 5, 7)]
            want = [s["net_cents"], s["rate_bps"], s["entitlement"], s["adjustment"]]
            for col, g, w in zip(("net_cents", "rate_bps", "entitlement", "adjustment"), got, want):
                if not isinstance(g, (int, float)) or abs(Decimal(str(g)) - Decimal(w)) > Decimal("0.0001"):
                    raise RefreshError(
                        f"recalculated Summary row {i} ({s['group']} {s['quarter']}) {col} = {g!r}, "
                        f"expected {w}")
    return True


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def refresh(args):
    try:
        as_of = dt.date.fromisoformat(args.as_of)
    except ValueError as exc:
        raise RefreshError(f"--as-of {args.as_of!r} is not a YYYY-MM-DD date") from exc
    source = Path(args.source)
    output = Path(args.output)
    previous = Path(args.previous) if args.previous else None
    if not source.is_file():
        raise RefreshError(f"source workbook {source} does not exist")
    if output.suffix.lower() != ".xlsx":
        raise RefreshError("--output must be an .xlsx path")
    protected = [source.resolve()] + ([previous.resolve()] if previous else [])
    if output.resolve() in protected:
        raise RefreshError("--output must not overwrite the source or the previous approved close")
    if output.resolve().parent.name == "archive":
        raise RefreshError("refusing to write into an archive directory of approved closes")

    source_bytes = source.read_bytes()
    try:
        wb = load_workbook(source, data_only=False)
    except Exception as exc:
        raise RefreshError(f"cannot read source workbook {source}: {exc}") from exc
    for name in SOURCE_SHEETS:
        if name not in wb.sheetnames:
            raise RefreshError(f"source workbook is missing sheet {name!r}")

    lines, products, aliases, contracts = load_reference(wb)
    selected = select_events(read_table(wb, "Events"), as_of)
    detail, voids = build_detail(selected, as_of, lines, products, aliases)
    prior = load_previous(previous) if previous else {}

    nets = {}
    for d in detail:
        key = (d["group"], d["quarter"])
        nets[key] = nets.get(key, 0) + d["eligible_cents"]
    summary_rows = []
    for key in sorted(set(nets) | set(prior), key=lambda k: (k[1], k[0])):
        net = max(0, nets.get(key, 0))
        rate = rate_for(contracts, key, net)
        if rate is None:
            if key in nets:
                raise RefreshError(f"Contracts has no zero-threshold tier for {key[0]} {key[1]}")
            rate = Decimal(0)
        entitlement = entitlement_for(net, rate)
        prev = prior.get(key, Decimal("0.00"))
        summary_rows.append({
            "group": key[0], "quarter": key[1], "net_cents": net,
            "rate_bps": int(rate) if rate == rate.to_integral_value() else rate,
            "entitlement": entitlement, "previous": prev, "adjustment": entitlement - prev,
        })

    output.parent.mkdir(parents=True, exist_ok=True)
    out_tmp = output.with_name(f".{output.stem}.tmp.xlsx")
    try:
        write_workbook(source, out_tmp, detail, summary_rows)
        recalculated = False if args.skip_recalc_check else recalc_check(out_tmp, summary_rows)
        os.replace(out_tmp, output)
    finally:
        if out_tmp.exists():
            out_tmp.unlink()

    adjustment_total = sum((s["adjustment"] for s in summary_rows), Decimal("0.00"))
    report = {
        "as_of": as_of.isoformat(),
        "source": str(source),
        "source_sha256": hashlib.sha256(source_bytes).hexdigest(),
        "previous_close": str(previous) if previous else None,
        "previous_sha256": hashlib.sha256(previous.read_bytes()).hexdigest() if previous else None,
        "output": str(output),
        "active_event_count": len(detail),
        "active_buy_count": sum(1 for d in detail if d["kind"] == "BUY"),
        "active_return_count": sum(1 for d in detail if d["kind"] == "RETURN"),
        "ineligible_event_ids": sorted(d["event_key"] for d in detail if not d["eligible"]),
        "void_event_ids": sorted(voids),
        "detail_total_cents": sum(d["eligible_cents"] for d in detail),
        "entitlement_total": float(sum((s["entitlement"] for s in summary_rows), Decimal("0.00"))),
        "previous_entitlement_total": float(sum((s["previous"] for s in summary_rows), Decimal("0.00"))),
        "adjustment_total": float(adjustment_total),
        "libreoffice_recalc_verified": recalculated,
        "summary": [{
            "group": s["group"], "quarter": s["quarter"], "net_cents": s["net_cents"],
            "rate_bps": float(s["rate_bps"]) if isinstance(s["rate_bps"], Decimal) else s["rate_bps"],
            "entitlement": float(s["entitlement"]), "previous_entitlement": float(s["previous"]),
            "adjustment": float(s["adjustment"]),
        } for s in summary_rows],
    }
    report_path = output.parent / "reconciliation.json"
    report_path.write_text(json.dumps(report, indent=2) + "\n")
    return report, report_path


def main():
    parser = argparse.ArgumentParser(description="Refresh the supplier-rebate settlement workbook.")
    parser.add_argument("--source", required=True, help="source ERP workbook (read-only)")
    parser.add_argument("--as-of", required=True, help="cutoff date YYYY-MM-DD")
    parser.add_argument("--output", required=True, help="settlement workbook to write")
    parser.add_argument("--previous", help="previous APPROVED close workbook (read-only)")
    parser.add_argument("--skip-recalc-check", action="store_true",
                        help="do not recalculate a copy with LibreOffice")
    args = parser.parse_args()
    try:
        report, report_path = refresh(args)
    except RefreshError as exc:
        print(f"refresh failed: {exc}", file=sys.stderr)
        return 2
    print(f"Wrote {args.output} and {report_path}: {report['active_event_count']} active events, "
          f"{len(report['void_event_ids'])} void, detail {report['detail_total_cents']} cents, "
          f"adjustment total {report['adjustment_total']:.2f}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

